async function  RenderArrayPositionPdf(pdfDoc, data ) {

  let page = pdfDoc.addPage()
  const {  height } = page.getSize()

  heightPg =  height - 30;


  
  let beta = 60;
  let fact = Math.ceil(data.length / beta);
  Array.from(Array(fact).keys()).map(ft=>{
   
    if(ft>0){
      page = pdfDoc.addPage();
      heightPg =  height - 30;
    }

    let arr = data.slice(ft*beta, (ft+1)*beta);
    arr && arr.map((item, Ind)=>{
      
      heightPg =  heightPg - item.yInc;
      if(item.line){
        page.drawRectangle({
          x: item.line.x,
          y: heightPg + (item.line.y),
          width: item.line.width,
          height: item.line.height,
          borderColor: rgb(0, 0, 0),
        });
      }
      if(item.label){
        page.drawText(item.label.value, {
          x: item.label.x,
          y:  heightPg,
          size: item.label.size,
          font: item.label.font,
          color: rgb(0, 0, 0),
        })
      }
      if(item.amount){
        page.drawText(item.amount.value, {
          x: item.amount.x,
          y:  heightPg,
          size: item.amount.size,
          font: item.amount.font,
          color: rgb(0, 0, 0),
        })
      }

    })
  })

}







export async function createPdf(data, param_general, cuentas_general, param_result, cuentas_result ) {
  const pdfDoc = await PDFDocument.create();
  pdfDoc.registerFontkit(fontkit);

  fonstP = await initializeFonts(pdfDoc);



 
  let {totalGP, listArr } = ResultSheetPdf(param_result, data?.result , cuentas_result );
  
  let bg_data = GenerateGSheetPdf(param_general, data?.general, cuentas_general, totalGP );

  RenderArrayPositionPdf(pdfDoc, listArr )
  RenderArrayPositionPdf(pdfDoc, bg_data )



  const pdfBytes = await pdfDoc.save();
  let blobUrl = blobfromArray(pdfBytes)
 

  window.open(blobUrl)
}

































